INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Bizarre', 'Pokémon Bizarre is a Spanish-language fangame created by developer MrGrossi, also author of District Dance Battle, Motor Casa Paco, Vaya Canicastañazos, Mauriçius Nativitatem, FDI, A Toda Pastilla and Louse on the Loose. You will give life to a character who has been forced to explore the quirky and amazing Pokemon region known as Quintueles. In the process you can train up to eight generations of Pokémon, visit eight different gyms, meet new stupid characters and embark on a multitude of missions that involve things such as going to a rave, fight malicious octopuses and chit-chat with the famous "Alien Fumeta".' FROM games WHERE igdb_id = 243995 ON CONFLICT (game_id, language_code) DO NOTHING;
