INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mixed Feelings: While You Were Away', 'Gale and Arthur are in a long-distance relationship, but Gale found himself feeling lonely without his partner. When he applies to work at a cafe, he meets his charismatic co-worker, Brycen. Brycen is so different from Arthur, yet he finds himself falling for him. Will he choose his new or old love?' FROM games WHERE igdb_id = 195682 ON CONFLICT (game_id, language_code) DO NOTHING;
