INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fursan al-Aqsa: The Knights of the Al-Aqsa Mosque', 'Fursan al-Aqsa: The Knights of the Al-Aqsa Mosque is an Action Game on which you play as Ahmad al-Falastini, a young Palestinian Student who was unjustly tortured and jailed by Israeli Soldiers for 5 years, had all his family killed by an Israeli Airstrike and now, after getting out from prison, seeks revenge against those who wronged him, killed his family and stolen his homeland, by joining a new Palestinian Resistance Movement called Fursan al-Aqsa: The Knights of the Al-Aqsa Mosque.' FROM games WHERE igdb_id = 166499 ON CONFLICT (game_id, language_code) DO NOTHING;
