INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Round Invaders Rush 2', 'Observing strange movements. The creature seems to be capable doing much more than we''ve ever expected from such a thick, useless blob of gel... No! NO! He can actually RUSH! The experiment is going out of control. He will eat ALL of our ice cream! Our secret samples are in danger!' FROM games WHERE igdb_id = 214039 ON CONFLICT (game_id, language_code) DO NOTHING;
