INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1428: Shadows over Silesia', 'Shadows over Silesia is a dark action adventure game with fantasy elements, set in real medieval Europe. With true historical events in the background, you can mainly expect challenging puzzles and difficult battles, but also stealth scenes and important decisions. You will come across possessed devil worshipers, sexual demons, and beasts from hell, as well as creatures well-known from European mythology.' FROM games WHERE igdb_id = 130261 ON CONFLICT (game_id, language_code) DO NOTHING;
