INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'McSpace Colosseum', 'McSpace Colosseum is a dungeon crawler fully packed with action and roguelite elements. Discover all kind of worlds, collect crazy gadgets &relics, and face blood-lusting bosses with up to 4 friends. Will you rise as the strongest gladiator in this whacky and limitless reality show?' FROM games WHERE igdb_id = 150399 ON CONFLICT (game_id, language_code) DO NOTHING;
