INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhythmic Keyboard', 'Rhythmic Keyboard is a music-based typing game with integration of a talent system that allows for the player to increase their effectiveness. Procedurally spawned keys inhibit pattern formation, so reaction speed and hand/eye coordination are a priority -- not memorization.' FROM games WHERE igdb_id = 199692 ON CONFLICT (game_id, language_code) DO NOTHING;
