INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Em-A-Zurvival', 'When Andrew wakes up from his apartment, he is greeted by an unfriendly shriek. Oblivious to the rising epidemic, he innocently wonders around the apartment and comes across Frank…who is eating his wife. He now tries to escape his apartment that is now filled with man-eating humans.' FROM games WHERE igdb_id = 143970 ON CONFLICT (game_id, language_code) DO NOTHING;
