INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Pen Color Book', 'This coloring book game will let your kid(s) draw by finger touch anything from their imagination or color, decorate the ready to use templates included, in order to create their own unique paintings. Many painting tools are available to help them, including pencils, markers, color bucket, stickers, magic pen, color spray, patterns, with undo/redo capabilities. Once kids are done with their creations, those are automatically saved into device memory with the possibility to be later erased to start over and over...' FROM games WHERE igdb_id = 187488 ON CONFLICT (game_id, language_code) DO NOTHING;
