INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Katana Exa Label', 'Crimson Katana: exA Label is a fresh take on Cave''s sidescrolling arcade shooter Akai Katana incorporating elements from its Xbox 360 port. In addition to its several game modes, this release features several bonus options available in all game modes. A soundtrack selection menu lets players choose between the original arcade soundtrack, the Xbox 360 arranged soundtrack, or a new FM synth arranged soundtrack created by Keishi Yonao. A loop selection option lets players choose to begin from the harder second loop instead of from the beginning of the game. When played in English, dialogue is now subtitled for the first time.' FROM games WHERE igdb_id = 365112 ON CONFLICT (game_id, language_code) DO NOTHING;
