INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Swords Firelink', 'Dark Swords: Fire link is a 2D metroidvania game with a large locations to explore, fight with a lot creatures and epic bosses, and greats skills and power-ups to acquire. Have some of the better features that defines the 8/16-bits era, games like Ninja Gaiden, Super Ghost and Ghouls, Megaman, Castlevania and Super Metroid. Also, it gets inspired by the Dark Souls series, Hollow Knight and Blasphemous.' FROM games WHERE igdb_id = 198207 ON CONFLICT (game_id, language_code) DO NOTHING;
