INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sthell', 'STHELL is a fast-paced arena shooter that will take you to a forgotten swamp that was once a test site of Kiratron Industries. Take on hundreds of machines left to rust for years. It''s a battle you probably won''t win, but make a stand and your resilience will be etched in their memory chips forever.' FROM games WHERE igdb_id = 152768 ON CONFLICT (game_id, language_code) DO NOTHING;
