INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burrow of the Fallen Bear: A Gay Furry Visual Novel', 'A gay furry visual novel, full of fantasy and RPG elements. Experience Krile’s journey before he saves the Furry Heroes, Meet 3 unique hot adventurers, Fight with them, Buy items that impact your story, Unlock branches, Explore the Fallen Bear’s burrow. Everything through a classic choice system.' FROM games WHERE igdb_id = 203636 ON CONFLICT (game_id, language_code) DO NOTHING;
