INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SBK 22', 'The Official Game of the 2022 MOTUL FIM Superbike World Championship is the perfect replica of what happens in the real-life, featuring the event calendar, official roster and teams’ pit environments with absolutely photorealistic effects and animated character models. Players will test their skills racing in the boots of the best riders, stepping in all the competitive WorldSBK Official tracks meaning unpredictable and adrenaline challenges.' FROM games WHERE igdb_id = 204630 ON CONFLICT (game_id, language_code) DO NOTHING;
