INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paper Cut Mansion', 'A horror game about a guy lost in a mansion where everything is made of cardboard. Escaping from the house won’t be an easy task! Some of the rooms are locked and the player will need to solve different types of riddles to advance through the levels. The hints to solve the riddles will be hidden inside the furniture of the mansion but watch out! You don’t know what else is lurking inside those cardboard models!' FROM games WHERE igdb_id = 86512 ON CONFLICT (game_id, language_code) DO NOTHING;
