INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hell Pie', 'Hell Pie is a single player 3D-Platformer which empowers the player with an extensive set of moves based on a swing mechanic and lets him explore a combination of twisted large worlds and small challenging levels. Fighting against enemies, collecting weird cake ingredients and interactions with bizarre characters complement the gameplay. Our target audience are fans of old-school Action-Adventures and gamers who loved to play N64 classics such as Mario 64 or Banjo-Kazooie. Right now the game is in production and will be released in the 3rd quarter of 2020.' FROM games WHERE igdb_id = 118313 ON CONFLICT (game_id, language_code) DO NOTHING;
