INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tic-Tac-Tanks', 'Tic Tac Tanks is a tactical coffee break puzzle game inspired by Tic-Tac-Toe. Command toy-like vehicles in each challenging puzzle. Place your units on the grid thoughtfully. Each unit''s placement will affect how the battle plays out. Line up your units on the rows and columns to score bonus points.' FROM games WHERE igdb_id = 195214 ON CONFLICT (game_id, language_code) DO NOTHING;
