INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tilefinder', 'Tilefinder is an indie rogue-like turn-based grid RPG in which you slay hordes of monsters through a procedurally generated kingdom to find the legendary Tile shards! While excavating the castle, a floor tile came loose, releasing eldritch corruption that overtook the kingdom. Now, with the floor tile broken, it is your job to bring all the pieces together and assemble the Tile to seal the evil back where it came from!' FROM games WHERE igdb_id = 196857 ON CONFLICT (game_id, language_code) DO NOTHING;
