INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brigadoon-the-quest-of-time', 204485, '2022-06-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5c6m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1phk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brigadoon: The Quest of Time', 'Based off the original book and musical written by Alan Jay Lerner comes a brand new indie title inspired by the ever-popular The Legend of Zelda: Majora''s Mask! It follows a similar formula with a time cycle forcing you to do a set of tasks at a certain time in order to make progress. The game takes place in Scotland where a visitor named Tommy Albright from New York was on a hunting trip but gets lost, and finds himself stuck in the land of Brigadoon, which is cursed to appear for one day and disappear for 100 years! Help Tommy learn the secrets of Brigadoon and break the spell so he can escape! Help NPCs in a number of quests! Solve puzzles and unlock secrets! This game will have many surprises along the way, so it''s guaranteed to be a blast!' FROM games WHERE igdb_id = 204485 ON CONFLICT (game_id, language_code) DO NOTHING;
