INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marissa Is Now Idle', 'Marissa Is Now Idle is a visual novel made for the Dying MMO Jam, that takes place on a computer in 2003. After logging in, you find your internet friend Marissa sitting next to you and have one last conversation.
